// Normalise the Polymarket response into `markets` + `bands` rows.
//
// CONFIRMED target columns (sql/ad4_99_verify.sql section 7):
//   markets(market_id uuid, city_key, resolution_date, event_slug, title,
//           unit, band_count, closed, condition_id, ...)
//   bands(band_id uuid, market_id uuid, band_index int, band_label,
//         band_lo, band_hi, open_low, open_high, condition_id,
//         token_yes, token_no)
//
// NOT GROUNDED: the shape of the upstream payload. Adjust the field reads
// below to match what your endpoint returns - the OUTPUT shape above is
// the part that must not change.
const cities = $('Load cities').all().map(i => i.json).flat();
const raw = $('Fetch markets').all().map(i => i.json).flat();

const markets = [], bands = [];
let skippedNoCity = 0;

for (const m of raw) {
  if (!m) continue;
  const slug = String(m.slug || m.event_slug || '');
  const city = cities.find(c => c && c.city_key && slug.includes(c.city_key)) || null;
  if (!city) { skippedNoCity++; continue; }     // not one of our cities

  const marketId = m.market_id || m.id;         // must be stable across runs
  if (!marketId) continue;

  const outcomes = m.outcomes || m.bands || m.tokens || [];

  markets.push({
    market_id: marketId,
    city_key: city.city_key,
    resolution_date: String(m.resolution_date || m.endDate || m.end_date || '').slice(0, 10) || null,
    event_slug: slug || null,
    title: m.title || m.question || null,
    unit: city.unit || 'C',
    band_count: outcomes.length || null,
    closed: Boolean(m.closed),
    condition_id: m.conditionId || m.condition_id || null,
    last_seen_at: new Date().toISOString(),
  });

  // One band per outcome. band_lo/band_hi are the numeric bounds;
  // open_low/open_high mark the unbounded tails ("27 or below", "31+").
  outcomes.forEach((o, idx) => {
    if (!o) return;
    const bandId = o.band_id || o.id;
    if (!bandId) return;
    const toks = o.tokens || [];
    bands.push({
      band_id: bandId,
      market_id: marketId,
      band_index: o.band_index ?? idx,
      band_label: o.label || o.band_label || null,
      band_lo: o.band_lo ?? o.lo ?? null,
      band_hi: o.band_hi ?? o.hi ?? null,
      open_low: Boolean(o.open_low),
      open_high: Boolean(o.open_high),
      condition_id: o.conditionId || o.condition_id || m.conditionId || m.condition_id || null,
      token_yes: o.token_yes || toks[0] || null,
      token_no:  o.token_no  || toks[1] || null,
    });
  });
}

return [{ json: { markets, bands, n_markets: markets.length,
                  n_bands: bands.length, skipped_no_city: skippedNoCity,
                  n_raw: raw.length } }];

const p = $('Parse markets + bands').first().json;
if (p.n_markets === 0) {
  throw new Error(
    `Parsed 0 markets from ${p.n_raw} payload items ` +
    `(${p.skipped_no_city} skipped: slug matched none of your cities). ` +
    `Nothing was written. Either the Polymarket endpoint in Config is wrong, ` +
    `or its response shape does not carry slug/id/outcomes. Open your ` +
    `original P0.2 and copy its URL across.`);
}
return [{ json: p }];

const p = $('Parse markets + bands').first().json;
const rows = (p.n_markets || 0) + (p.n_bands || 0);
const summary = `AD4 P0.2: ${p.n_markets} markets, ${p.n_bands} bands upserted ` +
                `from ${p.n_raw} payload items (${p.skipped_no_city} not our cities).`;
const status = rows > 0 ? 'ok' : 'attention';
const detail = { n_markets: p.n_markets, n_bands: p.n_bands,
                 n_raw: p.n_raw, skipped_no_city: p.skipped_no_city };
return [{ json: {
  summary, status, rows,
  log: { p_job: 'P0.2_market_discovery', p_status: status, p_rows: rows,
         p_detail: { ...detail, summary, trigger: $execution.mode, execution_id: $execution.id } },
} }];

// Ask the database whether this run should do anything.
//
// n8n cannot be told from outside not to FIRE a schedule trigger, so the saving
// is here: returning no items stops every node below, and the execution ends
// having done two trivial requests instead of the whole job.
//
// settings.workflow_schedules owns the answer (sql/ad4_20_schedules.sql) and
// the Workflows page edits it. A manual or webhook run always proceeds - a Run
// button that obeyed the cadence would be a Run button that does nothing.
const d = $('Check schedule').first().json ?? {};
const decision = Array.isArray(d) ? d[0] : d;

// A gate that fails closed would silently disable every workflow the first
// time the settings row is missing or the RPC is absent. Fail OPEN: an
// unreachable gate means run, and say so in the log.
if (decision === null || decision === undefined || decision.run === undefined) {
  console.log('schedule gate unavailable - running anyway');
  return $input.all();
}

if (decision.run === false) {
  // Recorded, so a skipped run is visible on the Workflows page as a skip
  // rather than looking like a workflow that silently stopped working.
  return [{ json: { __skipped: true, reason: decision.reason || 'not scheduled',
                    minutes_since: decision.minutes_since ?? null,
                    every_minutes: decision.every_minutes ?? null } }];
}
return $input.all();

// Returning [] stops the workflow here. Everything below this node
// is skipped, which is the entire point of the gate.
const items = $input.all();
if (items.length === 1 && items[0].json && items[0].json.__skipped) {
  console.log('skipped: ' + items[0].json.reason);
  return [];
}
return items;
